const edge=cp.spawn("C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",["--headless=new","--disable-gpu","--no-first-run","--remote-debugging-port=0","--user-data-dir="+profile,"about:blank"],{stdio:["ignore","ignore","pipe"]});
let ws,seq=0;const pending=new Map(),errors=[],result={};const timeout=setTimeout(()=>{edge.kill();console.error("Remediation UI timed out");process.exit(1)},105000);
(async()=>{try{
const address=await new Promise((resolve,reject)=>{let out="";edge.stderr.on("data",b=>{out+=b.toString();const m=out.match(/DevTools listening on (ws:\/\/[^\s]+)/);if(m)resolve(m[1])});edge.on("error",reject);edge.on("exit",code=>reject(Error("Edge exited "+code)))});
const tabs=await (await fetch("http://"+new URL(address).host+"/json/list")).json();ws=new WebSocket(tabs.find(t=>t.type==="page").webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==="Runtime.exceptionThrown")errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result)}};
const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}))});
const evaluate=async expression=>{const r=await call("Runtime.evaluate",{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value};
const ready=()=>evaluate("(async()=>{for(let i=0;i<150;i++){if(document.querySelector('.plan-history'))return true;await new Promise(r=>setTimeout(r,100))}throw Error('App not ready')})()");
const reload=async()=>{await call("Page.reload",{ignoreCache:true});await ready()};const shot=async name=>{const r=await call("Page.captureScreenshot",{format:"png"});fs.writeFileSync(path.join(evidence,name+".png"),Buffer.from(r.data,"base64"))};
await call("Runtime.enable");await call("Page.enable");await call("Emulation.setDeviceMetricsOverride",{width:1600,height:1050,deviceScaleFactor:1,mobile:false});await call("Page.navigate",{url:"http://127.0.0.1:4196/"});await ready();
await evaluate(scripts.primarySeed);await reload();result.firstLoad=await evaluate(scripts.primaryCheck);await shot('current-key-migration-visible');
await reload();result.secondLoad=await evaluate(scripts.primaryCheck);
if(errors.length)throw Error("Browser exceptions: "+errors.join("\n"));result.errors=errors;fs.writeFileSync(path.join(evidence,"current-key-results.json"),JSON.stringify(result,null,2));console.log(JSON.stringify(result));await call("Browser.close");ws.close();
}catch(e){console.error(e.stack);process.exitCode=1;if(ws)ws.close();edge.kill()}finally{clearTimeout(timeout);setTimeout(()=>{try{fs.rmSync(profile,{recursive:true,force:true})}catch{}},1000)}})();
